using System.Collections;
using VisualRelay.Core.Configuration;
using VisualRelay.Domain;

namespace VisualRelay.Core.Execution;

internal sealed record TargetCommandEnvironment(
    IReadOnlyDictionary<string, string> Overrides,
    IReadOnlySet<string> Remove);

public sealed partial class SwivalSubagentRunner
{
    // Build environment overrides shared by every nono-wrapped invocation (the
    // swival stage and the SandboxedTestRunner verify path). Two jobs:
    // (1) redirect transitive-dependency caches into ~/.config/swival (already in
    //     the swival profile write-allow list) so nono's vr-guard sandbox does not
    //     block them — see nono-grant-swival-workspace-writes (stage 6);
    // (2) stop `dotnet test` leaving orphaned descendants that outlive the finished
    //     tests and keep the nono wrapper alive past completion (the stage-5/9
    //     timeout-after-tests-pass) — defence in depth with the runner's idle-reap.
    internal static IReadOnlyDictionary<string, string> BuildSandboxEnvironment(RelayConfig config)
    {
        var home = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
        var env = new Dictionary<string, string>
        {
            ["HF_HOME"] = Path.Combine(home, ".config", "swival", "huggingface"),
            ["XDG_CACHE_HOME"] = Path.Combine(home, ".config", "swival", "cache"),
            ["UV_CACHE_DIR"] = Path.Combine(home, ".config", "swival", "uv-cache"),
            // Stop Python under nono writing .pyc into its (denied) stdlib dir, e.g. the Homebrew python@3.14 Cellar — that triggers an interactive ~50-path "Review denied paths" prompt that blocks the run; PYCACHEPREFIX redirects any re-enabled bytecode to a write-allowed dir.
            ["PYTHONDONTWRITEBYTECODE"] = "1",
            ["PYTHONPYCACHEPREFIX"] = Path.Combine(home, ".config", "swival", "pycache"),
            // MSBUILDDISABLENODEREUSE=1 makes MSBuild node-reuse workers exit instead of lingering past the tests; the telemetry opt-out drops the background uploader. Both are ignored by non-.NET targets. (UseSharedCompilation=false in the configured testCmd already disables the Roslyn build server.)
            ["MSBUILDDISABLENODEREUSE"] = "1",
            ["DOTNET_CLI_TELEMETRY_OPTOUT"] = "1",
        };

        if (OperatingSystem.IsWindows())
        {
            // Windows Python defaults stdout to the legacy cp1252 console code page,
            // so swival's print() of model output crashes on a non-ASCII character
            // (e.g. a non-breaking hyphen). Force UTF-8 mode so the agent's output
            // and the files it writes are encoded consistently.
            env["PYTHONUTF8"] = "1";
            env["PYTHONIOENCODING"] = "utf-8";
        }

        return env;
    }

    /// <summary>
    /// Builds the target-repo command environment by starting from the
    /// pre-devshell user snapshot (when available), then applying VR's sandbox
    /// overrides on top. Returns a <see cref="TargetCommandEnvironment"/> that
    /// provides both the override dictionary and a removal set: when a valid
    /// snapshot exists, every key present in the current process environment
    /// but NOT in the overrides is placed in <c>Remove</c> so the child
    /// process does not inherit devshell-only keys (e.g. <c>DOTNET_ROOT</c>).
    /// When no snapshot exists — packaged/brew installs — falls back to the VR
    /// overrides alone with an empty removal set (byte-identical behavior to
    /// before).
    /// </summary>
    internal static TargetCommandEnvironment BuildTargetCommandEnvironment(
        RelayConfig config,
        IEnvironmentAccessor? accessor = null,
        IReadOnlyDictionary<string, string>? processEnv = null)
    {
        var snapshot = UserEnvSnapshot.Load(accessor);
        var processEnvironment = processEnv ?? SnapshotProcessEnv();

        // No/invalid snapshot: snapshot is null OR snapshot lacks a PATH key.
        // Packaged/brew path — return sandbox overrides only, no removals.
        if (snapshot is null || !snapshot.ContainsKey("PATH"))
        {
            return new TargetCommandEnvironment(
                BuildSandboxEnvironment(config),
                new HashSet<string>());
        }

        // Valid snapshot: start from the user's pre-devshell env, then apply VR
        // overrides on top (VR wins on collision).
        var merged = new Dictionary<string, string>(snapshot);
        foreach (var kvp in BuildSandboxEnvironment(config))
            merged[kvp.Key] = kvp.Value;

        // Every key present in the current process environment that is NOT a
        // key of merged is a devshell-only key — strip it from the child.
        var remove = new HashSet<string>();
        foreach (var key in processEnvironment.Keys)
        {
            if (!merged.ContainsKey(key))
                remove.Add(key);
        }

        return new TargetCommandEnvironment(merged, remove);
    }

    /// <summary>
    /// Snapshots the real process environment into a dictionary for diffing.
    /// </summary>
    private static IReadOnlyDictionary<string, string> SnapshotProcessEnv()
    {
        var dict = new Dictionary<string, string>();
        foreach (DictionaryEntry entry in Environment.GetEnvironmentVariables())
        {
            var key = entry.Key as string;
            var value = entry.Value as string;
            if (key is not null && value is not null)
                dict[key] = value;
        }
        return dict;
    }
}

