    // devshell but the user's pre-devshell snapshot does NOT have it.
    var processEnv = new Dictionary<string, string>
    {
        ["DOTNET_ROOT"] = "/nix/store/x/share/dotnet",
        ["HOME"] = "/home/user",
        ["PATH"] = "/usr/local/bin:/usr/bin:/bin",
